function developerCredits(){return `<section class="developer-credits"><div class="dev-intro"><span class="dev-eyebrow">QUEM CONSTRÓI ESTE FUTURO</span><h3>Desenvolvedores</h3><p>Tecnologia, cultura e possibilidades em uma cidade para explorar.</p></div><div class="dev-grid">${[{id:'gb2212',initial:'GB',name:'Gustavo Barreto'},{id:'vitor-lucas',initial:'VL',name:'Vitor Lucas'}].map(d=>`<article class="dev-card"><div class="dev-monogram" aria-hidden="true">${d.initial}</div><div class="dev-role">DESENVOLVIMENTO FULL-STACK</div><h4>${d.name}</h4><span class="dev-handle">@${d.id}</span><p>Desenvolvedor full-stack</p><a class="dev-link" href="https://github.com/${d.id}" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 2a10 10 0 0 0-3.16 19.49c.5.09.68-.22.68-.48v-1.86c-2.78.6-3.37-1.18-3.37-1.18-.45-1.16-1.11-1.47-1.11-1.47-.91-.62.07-.61.07-.61 1 .07 1.53 1.03 1.53 1.03.89 1.53 2.34 1.09 2.91.83.09-.65.35-1.09.64-1.34-2.22-.25-4.55-1.11-4.55-4.94 0-1.09.39-1.98 1.03-2.68-.1-.25-.45-1.27.1-2.65 0 0 .84-.27 2.75 1.02A9.6 9.6 0 0 1 12 6.82a9.6 9.6 0 0 1 2.5.34c1.91-1.29 2.75-1.02 2.75-1.02.55 1.38.2 2.4.1 2.65.64.7 1.03 1.59 1.03 2.68 0 3.84-2.34 4.69-4.57 4.94.36.31.68.92.68 1.85v2.75c0 .27.18.58.69.48A10 10 0 0 0 12 2Z"/></svg>Ver perfil no GitHub <span aria-hidden="true">↗</span></a></article>`).join('')}</div><div class="research-team"><h3>Equipe de pesquisa e apresentação</h3><p>43 participantes · pesquisa, design e apresentação</p><div class="team-grid">${PROJECT_TEAM.map(p=>`<article class="team-card"><h4>${esc(p.name)}</h4><div class="team-roles">${p.roles.map(r=>`<span>${r}</span>`).join('')}</div></article>`).join('')}</div></div></section>`;}
